"""Industry-specific advisory procurement briefs and printable scope worksheets."""
import csv,re,json
from pathlib import Path

def build_hiring_library(page,heading,e,firms,urls,out,base):
 root=Path(__file__).resolve().parent
 slug=lambda s:re.sub('[^a-z0-9]+','-',s.lower()).strip('-')
 industries=[]
 for row in csv.reader((root/'data/hiring-industries.tsv').open(),delimiter='|'):
  name,context,records,example,question=row
  industries.append(dict(name=name,slug=slug(name),context=context,records=records.split('; '),example=example,question=question))
 decisions=[]
 for row in csv.reader((root/'data/hiring-decisions.tsv').open(),delimiter='|'):
  key,phrase,context,records,questions,deliverable,category=row
  decisions.append(dict(slug=key,phrase=phrase,context=context,records=records.split('; '),questions=questions.split('; '),deliverable=deliverable,category=category))
 def link(u,t):return '<a href="'+e(u)+'">'+e(t)+'</a>'
 def card(u,title,desc):return '<a class="guide-card" href="'+e(u)+'"><span class="eyebrow">Advisor hiring brief</span><h3>'+e(title)+'</h3><p>'+e(desc)+'</p><span>Prepare the scope ↗</span></a>'
 def briefurl(i,d):return '/hiring/'+i['slug']+'/'+d['slug']+'/'
 def questions(i,d):
  return [i['question'],*d['questions'],'Which information is missing, and who will obtain it?','What are the complete fees, exclusions, and support dates for this work?']
 def rows(i,d):
  return [(q,'','','') for q in questions(i,d)]
 target=[]
 intro='Choose the work you need help evaluating. Each brief combines an operating context, a decision-specific document list, interview questions, and a scope worksheet you can use with prospective advisors.'
 page('/hiring/','Tax advisor hiring briefs by industry and business decision','Find industry-specific questions, document lists, and printable worksheets for choosing a tax advisor around an actual business decision.',heading('THE ADVISORY BUYER’S DESK','Find an advisor for the decision ahead.',intro)+'<article class="prose narrow"><h2>A more useful first conversation.</h2><p>Describe your business, name the next decision, and ask for the work that connects them. These briefs help you prepare an inquiry and compare proposals. They do not establish that a particular tax position applies to you or that a listed firm offers every service.</p><p><a href="/hiring/decisions/">Browse by decision</a> or choose your industry below.</p></article><section class="section"><div class="grid">'+''.join(card('/hiring/'+i['slug']+'/',i['name'],i['context'].capitalize()+'.') for i in industries)+'</div></section>',kind='CollectionPage')
 page('/hiring/decisions/','Tax advisor selection by planning decision','Explore tax professional hiring questions for business growth, transactions, ownership changes, property, records, and team coordination.',heading('START WITH THE WORK','Which decision needs an advisor?','Select a decision, then choose your industry for a more specific interview and document brief.')+'<section class="section"><div class="grid">'+''.join(card('/hiring/decisions/'+d['slug']+'/',d['phrase'].capitalize(),d['context']) for d in decisions)+'</div></section>',kind='CollectionPage')
 for d in decisions:
  page('/hiring/decisions/'+d['slug']+'/', 'Hiring a tax advisor for '+d['phrase'], 'Compare advisor scope for '+d['phrase']+'. Choose an industry for records, questions, and a proposal worksheet.',heading('ADVISORY ENGAGEMENT RESEARCH',d['phrase'].capitalize(),d['context'])+'<article class="prose narrow"><h2>The work to define.</h2><p>Ask for '+e(d['deliverable'])+'. Confirm the professionals, documents, timing, and price before authorizing the work.</p><h2>Questions to resolve.</h2><ul>'+''.join('<li>'+e(q)+'</li>' for q in d['questions'])+'</ul></article><section class="section"><h2>Choose your operating context</h2><div class="grid">'+''.join(card(briefurl(i,d),i['name'],i['example']) for i in industries)+'</div></section>',kind='CollectionPage')
 for i in industries:
  page('/hiring/'+i['slug']+'/', 'Tax advisor hiring guide for '+i['name'].lower(),'Choose a tax advisor for '+i['name'].lower()+': industry records, decision-specific interviews, and scope comparison worksheets.',heading('INDUSTRY ADVISORY RESEARCH','Tax advisor research for '+i['name'].lower(), 'Organize '+i['context']+' before comparing advisory proposals.')+'<article class="prose narrow"><h2>Make the operating context clear.</h2><p>'+e(i['example'])+'</p><p>Start with '+e(', '.join(i['records']))+'. '+e(i['question'])+'</p><p>Choose the decision closest to your actual needs. A worksheet helps you compare a written proposal; it does not recommend a tax position or establish an advisor’s experience.</p></article><section class="section"><div class="grid">'+''.join(card(briefurl(i,d),d['phrase'].capitalize(),d['context']) for d in decisions)+'</div></section>',kind='CollectionPage')
  for di,d in enumerate(decisions):
   path=briefurl(i,d);title='Tax advisor for '+i['name'].lower()+': '+d['phrase']
   desc='For '+i['name'].lower()+' considering '+d['phrase']+': records to prepare, provider questions, and a printable scope worksheet.'
   doclist=list(dict.fromkeys(i['records']+d['records']))
   workbook=out/path.strip('/')/'scope-worksheet.csv';workbook.parent.mkdir(parents=True,exist_ok=True)
   with workbook.open('w',newline='') as f:
    writer=csv.writer(f);writer.writerow(['Industry',i['name']]);writer.writerow(['Decision',d['phrase']]);writer.writerow(['Proposed output',d['deliverable']]);writer.writerow([]);writer.writerow(['Question','Provider response','Responsible professional','Deadline / fee']);writer.writerows(rows(i,d))
   qhtml=''.join('<li>'+e(q)+'</li>' for q in questions(i,d))
   # Every page supplies a real local worksheet; no document uploads or invented firm claims.
   worksheet='<section class="scope-workbook"><h2>Your scope comparison worksheet</h2><p>Use public business context here. Keep tax returns and private financial records for a secure process agreed with your advisor.</p><form class="scope-form">'+''.join('<label>'+e(label)+'<textarea rows="3" placeholder="'+e(placeholder)+'"></textarea></label>' for label,placeholder in [('Decision and deadline','What must be decided, and by when?'),('Existing team','Who handles the books, payroll, returns, and legal work?'),('Records and gaps',', '.join(doclist)),('Requested deliverable',d['deliverable'].capitalize()),('Provider answers and responsibilities','Record the written answers, owner of each action, timing, and fees.')])+'<button class="button" type="button" data-print-scope>Print this brief and your notes</button></form><p><a href="scope-worksheet.csv" download>Download the comparison worksheet (CSV)</a>. Notes stay in this page while it is open and are not submitted by this form.</p></section>'
   body=heading('INDUSTRY × DECISION',title,'Prepare a provider conversation around '+i['context']+'.')+'<nav class="pagination" aria-label="Research path">'+link('/hiring/','All industries')+link('/hiring/'+i['slug']+'/',i['name'])+link('/hiring/decisions/'+d['slug']+'/',d['phrase'].capitalize())+'</nav><div class="article-layout"><article class="prose"><p class="byline">Tax Strategist Directory editorial desk · October 9, 2026</p><h2>Define the work before comparing firms.</h2><p>'+e(d['context'])+'</p><h2>Why the operating context matters.</h2><p>For '+e(i['name'].lower())+', the brief needs to explain '+e(i['context'])+'. '+e(i['example'])+'</p><p>Use that context to request '+e(d['deliverable'])+'. Identify the decision still open, the date it becomes binding, and which existing advisors are already responsible for part of the work.</p><h2>Prepare a decision-ready record list.</h2><ul>'+''.join('<li>'+e(x.capitalize())+'</li>' for x in doclist)+'</ul><p>Mark each item as available, incomplete, or held by another professional. Ask the candidate what it needs before quoting or performing analysis. A record gap should become an assigned task with a deadline, rather than an assumption that the information is complete.</p><h2>Interview the person who would do the work.</h2><ul>'+qhtml+'</ul><h2>What a useful proposal should settle.</h2><p>Request a named professional, the records reviewed, a defined output, implementation assignments, support dates, and the complete fee. Ask which work requires a separate engagement with a preparer, attorney, administrator, or specialist. Match every important deadline to a responsible person.</p><p>Compare the answer with the work you actually need. An impressive firm name or a broad service description cannot settle scope. If the proposal is unclear, record the open question and ask for clarification before engaging.</p>'+worksheet+'<h2>Research the provider as well as the proposal.</h2><p><a href="/firms/">Browse sourced firms</a>, review <a href="/guides/verify-tax-adviser-credentials/">credential checks</a>, and use the <a href="/compare/">proposal comparison tool</a>. This brief supports hiring research; it does not establish that any strategy applies or that every firm covers this work.</p></article><aside class="profile-aside"><span class="eyebrow">AE TAX ADVISORS</span><h3>Bring the next decision into focus.</h3><p>Explain your business, your current tax team, and the timeline ahead. Discuss whether AE’s advisory scope fits the work you need.</p><a class="button" href="https://www.aetaxadvisors.com/discovery?utm_source=taxstrategistdirectory&amp;utm_medium=industry_brief&amp;utm_campaign=advisory&amp;utm_content='+e(i['slug']+'-'+d['slug'])+'">Book an AE discovery call ↗</a><p><a href="/comparisons/ae-evidence-and-fit/">Review AE’s offering and fit</a></p><p class="fine">AE Tax Advisors owns and publishes this directory. A discovery call is a scope-and-fit conversation; advice requires an engagement.</p></aside></div><section class="section"><h2>Continue your research</h2><div class="grid">'+''.join(card(briefurl(i,x),x['phrase'].capitalize(),x['context']) for x in [decisions[(di+1)%len(decisions)],decisions[(di+2)%len(decisions)],decisions[(di+3)%len(decisions)]])+'</div></section><script src="/scope-workbook.js" defer></script>'
   page(path,title,desc,body,kind='Article',schema={'author':{'@type':'Organization','name':'Tax Strategist Directory editorial desk'},'datePublished':'2026-10-09','dateModified':'2026-10-09'})
   target.append({'url':base+path,'primary_keyword':'tax advisor for '+i['name'].lower()+' '+d['phrase'],'secondary_keywords':'how to choose a tax advisor for '+i['name'].lower()+' '+d['phrase']+'; '+i['name'].lower()+' '+d['phrase']+' advisor questions','industry':i['name'],'decision':d['phrase'],'intent':'commercial research','volume':'not measured'})
 (out/'scope-workbook.js').write_text("document.addEventListener('click',event=>{if(event.target.closest('[data-print-scope]'))window.print();});\n")
 with (root/'data/keyword-map.csv').open('w',newline='') as f:
  writer=csv.DictWriter(f,fieldnames=list(target[0]));writer.writeheader();writer.writerows(target)
 (root/'data/hiring-build-report.json').write_text(json.dumps({'industries':len(industries),'decisions':len(decisions),'decisionBriefs':len(target),'worksheetDownloads':len(target),'keywordVolume':'not measured; these are intent-specific target phrases, not claimed rankings'},indent=2))
